gchar *insight_ai_suggested_command(GtkWidget *controller) { Assistant *a=g_object_get_data(G_OBJECT(controller),STATE);return a && !a->closed && !a->busy && a->response && insight_ai_command_valid(a->response->command) ? g_strdup(a->response->command):NULL; }
